const pending = new Map<string, Promise<unknown>>();
export function getCachedProject(id: string, load: () => Promise<unknown>) {
  const existing = pending.get(id);
  if (existing) return existing;
  const promise = load().catch(error => { pending.delete(id); throw error; });
  pending.set(id, promise);
  return promise;
}
export function clearProjectCache() { pending.clear(); }

